import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  cp,
  mkdir,
  mkdtemp,
  readFile,
  readdir,
  rm,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const directory = dirname(fileURLToPath(import.meta.url));
const root = resolve(directory, "../..");
const config = JSON.parse(
  await readFile(join(directory, "provenance.json"), "utf8"),
);
/** Hash immutable producer inputs and complete generated bytes. */
const hash = (bytes) => createHash("sha256").update(bytes).digest("hex");
const spec = await readFile(join(directory, "openapi.yaml"));
if (hash(spec) !== config.contractSha256)
  throw new Error("Pinned contract checksum mismatch");
const cache = join(tmpdir(), "1msg-openapi-generator");
await mkdir(cache, { recursive: true });
const jar = join(cache, `${config.generatorVersion}.jar`);
try {
  await readFile(jar);
} catch {
  const response = await fetch(
    `https://repo.maven.apache.org/maven2/org/openapitools/openapi-generator-cli/${config.generatorVersion}/openapi-generator-cli-${config.generatorVersion}.jar`,
  );
  if (!response.ok)
    throw new Error(`Generator download failed: ${response.status}`);
  const bytes = Buffer.from(await response.arrayBuffer());
  if (hash(bytes) !== config.generatorSha256)
    throw new Error("Generator checksum mismatch");
  await writeFile(jar, bytes);
}
if (hash(await readFile(jar)) !== config.generatorSha256)
  throw new Error("Cached generator checksum mismatch");
/** Recursively inventory only declared generated code, excluding hand-owned tests and package metadata. */
async function inventory(directory, prefix = "") {
  const result = {};
  for (const entry of (await readdir(directory, { withFileTypes: true })).sort(
    (a, b) => a.name.localeCompare(b.name),
  )) {
    const path = prefix + entry.name;
    // Descend only into ancestors or descendants of declared generated roots; unrelated authored files stay untouched.
    if (entry.isDirectory()) {
      // Match an ancestor or descendant of an explicitly declared generated directory.
      if (
        config.roots.some(
          (item) =>
            item.startsWith(path + "/") ||
            path.startsWith(item.replace(/\/$/, "") + "/") ||
            item.replace(/\/$/, "") === path,
        )
      )
        Object.assign(
          result,
          await inventory(join(directory, entry.name), `${path}/`),
        );
    } else {
      // Match complete generated roots and top-level Go files while preserving handwritten contract tests.
      if (
        config.roots.some((item) =>
          item.endsWith("/")
            ? path.startsWith(item)
            : item === "*.go"
              ? !path.includes("/") &&
                path.endsWith(".go") &&
                !path.endsWith("_test.go")
              : item === path,
        )
      )
        result[path] = hash(await readFile(join(directory, entry.name)));
    }
  }
  return result;
}
const temporary = await mkdtemp(join(tmpdir(), "1msg-native-generation-"));
try {
  const properties = Object.entries(config.additionalProperties)
    .map(([key, value]) => `${key}=${value}`)
    .join(",");
  const result = spawnSync(
    "java",
    [
      "-jar",
      jar,
      "generate",
      "-i",
      join(directory, "openapi.yaml"),
      "-g",
      config.generatorName,
      "-o",
      temporary,
      `--additional-properties=${properties},hideGenerationTimestamp=true`,
      "--global-property=apiTests=false,modelTests=false",
    ],
    { stdio: "inherit" },
  );
  if (result.status !== 0)
    throw new Error(`Generator failed: ${result.status}`);
  if (config.postprocess) {
    const processResult = spawnSync(
      process.execPath,
      [join(root, "quality/postprocess.mjs"), temporary],
      { stdio: "inherit" },
    );
    if (processResult.status !== 0)
      throw new Error("Generated compatibility transform failed");
  }
  const expected = await inventory(temporary);
  if (!Object.keys(expected).length)
    throw new Error("Generator produced no inventoried code");
  const inventoryPath = join(directory, "inventory.json");
  if (process.argv.includes("--write")) {
    const previous = await inventory(root);
    for (const path of Object.keys(previous))
      if (!(path in expected)) await rm(join(root, path));
    for (const path of Object.keys(expected)) {
      await mkdir(dirname(join(root, path)), { recursive: true });
      await cp(join(temporary, path), join(root, path));
    }
    await writeFile(inventoryPath, JSON.stringify(expected, null, 2) + "\n");
  } else {
    for (const actual of [
      await inventory(root),
      JSON.parse(await readFile(inventoryPath, "utf8")),
    ])
      if (JSON.stringify(actual) !== JSON.stringify(expected))
        throw new Error(
          "Generated drift: review producer then run node quality/generator/generate.mjs --write",
        );
  }
  console.log(
    `Verified ${Object.keys(expected).length} generated ${config.language} code paths`,
  );
} finally {
  await rm(temporary, { recursive: true, force: true });
}
